import{i as e,o as t,r as n,t as r}from"./app-CKIWtCsy.js";var i=JSON.parse(`{"path":"/%E3%80%90%E6%9B%B8%E7%B1%8D%E3%80%91%E6%82%A3%E8%80%85%E3%81%AE%E8%A9%B1%E3%81%AF%E5%8C%BB%E5%B8%AB%E3%81%AB%E3%81%A9%E3%81%86%E8%81%9E%E3%81%93%E3%81%88%E3%82%8B%E3%81%AE%E3%81%8B.html","title":"【書籍】患者の話は医師にどう聞こえるのか","lang":"en-US","frontmatter":{},"git":{},"readingTime":{"minutes":2.49,"words":748},"filePathRelative":"【書籍】患者の話は医師にどう聞こえるのか.md"}`),a={name:`【書籍】患者の話は医師にどう聞こえるのか.md`};function o(r,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[e(`<h1 id="【書籍】患者の話は医師にどう聞こえるのか" tabindex="-1"><a class="header-anchor" href="#【書籍】患者の話は医師にどう聞こえるのか"><span>【書籍】患者の話は医師にどう聞こえるのか</span></a></h1><p><a href="./雑多なメモ.html">雑多なメモ</a></p><p><a href="https://amzn.to/4sWcjiw" target="_blank" rel="noopener noreferrer">amazon: 患者の話は医師にどう聞こえるのか――診察室のすれちがいを科学する </a></p><h2 id="購入-2026-01-25-日" tabindex="-1"><a class="header-anchor" href="#購入-2026-01-25-日"><span>購入 2026-01-25 (日)</span></a></h2><p>親の付き添いで医者に話を聞く、という機会が何度かあったが、この高齢者医療の医者との面接というのは非常に難しいイベントだな、と感じていた。 高齢者は非常に難しい治療を必要とする事が多く、それは非常に複雑な説明となる。 一方高齢者は複雑な話を聞くのが、若い頃よりも得意ではなくなっている。 さらにその選択の結果に一番影響を受けるのはその高齢者自身だ。</p><p>この難しさについて分析されて、解決策とまでは行かなくても何かヒントになりそうな本でも無いかな？と思ってamazonを探していて見つけたのがこの本。 Kindleで買えるが他の電子書籍にはなさそう。</p><h2 id="医者側の話ばかりなのは期待はずれだが悪くない-2026-01-29-木" tabindex="-1"><a class="header-anchor" href="#医者側の話ばかりなのは期待はずれだが悪くない-2026-01-29-木"><span>医者側の話ばかりなのは期待はずれだが悪くない 2026-01-29 (木)</span></a></h2><p>7章まで読んだが、今の所医者の側の問題のあるコミュニケーションの話ばかりで、 患者の側の問題のあるコミュニケーションの話は全然無い。 タイトルの「患者の話は医師にどう聞こえるのか」に関しての話が無いのはいかんのではないか？</p><p>自分が本書を読み始めたモチベーションは、患者の側がどういう事に気をつけたらいいか、という事が知りたいというもの。 直接そうでなくても、患者のこういう話は医師にはこう聞こえるので期待したようには伝わらないですよ、 という事が分かればいいかと思って買ったのだけれど、そういう話が無い。 という事で期待外れだった。</p><p>だが、医療コミュニケーションの医者側の話として、特にその病気に対する効果の高さは、 色々と興味深い。 また、医者の側の話は、プログラマとユーザーの対話を考えた時のプログラマ側に参考になる部分があり、 期待していたのとは違うけれど読み物としては悪くない。</p><p>他人の病気の話を延々と読むのは、なんか憂鬱な気持ちになるので良くない部分はあるよなぁ。 寝る前に読むと夢見が悪くなったりする。 自分が病気になって医者に掛かっている時に読むのはやめた方が良さそうだな。健康な時に、寝る前以外で読むのが良さそう。</p><h2 id="_8章はなかなか良い-2026-02-06-金" tabindex="-1"><a class="header-anchor" href="#_8章はなかなか良い-2026-02-06-金"><span>8章はなかなか良い 2026-02-06 (金)</span></a></h2><p>9章まで読んだ。</p><p>この本は、色々なエピソードや研究結果が説明されるが、その結果何か分かりやすい結論が出る訳ではない。結果として散漫な印象を受ける。 けれどこのくらいの事しか言えないのが現時点の事実である、という事なんだろうな、という気はしてきた。 それが事実なら、この本は誠実な本という事になる。</p><p>そして色々なエピソードや研究の内容は、知りたかった事そのものでは無いが参考にはなる。 情報としての価値がこの本にはある気はしてきた。 解決策はわからないが、どういう問題があるかは分かる。</p><p>8章くらいからはよりどう聞こえるか、という問題に踏み込んだ内容になっているので、タイトルから期待するものに近い内容になってきている気はする。 でもやはり多くは「患者にどう聞こえるか」という話と「医者はもっとどうすべきか」という話であって、患者側の質問のハウツーでは無いが。 タイトルに内容が近づいてきたため、読んでの満足度も上がってきた気はする。</p><p>相変わらず重い病気の話をたくさん読むのは憂鬱になる部分はあるが、最後まで読もうかな、という気分にはなっている。</p><h2 id="期待していた本とは違ったが、知らない事は多かった-2026-02-13-金" tabindex="-1"><a class="header-anchor" href="#期待していた本とは違ったが、知らない事は多かった-2026-02-13-金"><span>期待していた本とは違ったが、知らない事は多かった 2026-02-13 (金)</span></a></h2><p>読み終わったので感想など。</p><p>なかなか良い本だったのかイマイチな本だったのかが自分の中で定まらない本だなぁ、という印象。 著者は明らかに専門性が高く、本には知らない情報が多く載っている。 知らない事を知る事を勉強になったというならこの本は勉強になった、と言うべき本に思う。</p><p>だが、この本を読んだ上で自分の行動に何か違いが生まれるか？というと…どうかなぁ。難しい気もする。 実際に医者と話をする時に何か変わる気がしない。 そういう点では役に立ってない気もする。 この本を読む一番のモチベーションは医者と話をする時に自分の行動を改善したい、 というものだったが、その目的は達成できていない気もする。</p><p>この本は患者と医者の間にコミュニケーションに問題があると、いつも医者の側で何を改善すべきか、という事を考える。 患者の側はどうしたら良かったのか、という話はほとんど無い。 患者は色々な人がいて、色々なコミュニケーションの取り方をし、それには難しさがある、という事が分かる。 だがどういう患者が良い患者か？という視点は無い。</p><p>だから患者の側のコミュニケーションの改善にはあまり役に立たない…と言っていいかは、ちょっと良く分からない。 自分は患者の側のチェックリストとかハウツーみたいなものを期待していた訳だが、 そういう直接的な答えよりも、こういう様々なケースを見る方が問題は正しく認識出来る可能性はある。 そういう点で安易な本よりもむしろ内容はしっかりしている印象を受けたし、 情報としてより価値があるのかもしれない。 ただ自分の行動に活かすのは難しいなぁ、と思った。 このどっちつかずの感想がこの本の素直な感想と思う。</p><p>医師にどう聞こえるのか？という本のタイトルの直接の答えは載っていなかったが、 最後まで読み終わるとこのタイトルに相応しい内容にはなっていたように思う。 この点については序盤での印象よりはいいタイトルだったように思う。 医師からどう見えるのかという事はそれなりに分かった気がする。</p><p>医師は良く勉強していて、専門性も高く、内容には信頼がおける。 医師の名を冠した中身の無い新書みたいな本よりもしっかりした本の印象を受ける。 ちゃんとリファレンスは書いてあるし、読み手をバカにしている感じは無い。 経験豊富な医師なんだろうなぁ、というのが透けて見える。</p><p>コミュニケーションの問題を扱う本の性質上、難病患者が多い。 難病の細かい解説を読み続けるのは、憂鬱な気持ちになる。 これは本の性質上必要な事かもしれないが、あまり何度も読みたい説明では無いなぁ、とは思った。 自分が大きな病気を患ってコミュニケーションを学ぼうと思ってこの本を読んだら相当ダメージを受けただろうなぁ、 と思うし、それはあまり良い事では無いとも思う。 健康な時に読むべき本だ。</p><p>最後まで読んだのできっと良い本だったという事なのかもしれないなぁ。 読んで損したとは感じていない気がする。</p><p>即物的なご利益は無かったが、人生のどこかでこういう本を読んで病について静かに考える、というのは必要な事なのかもなぁ。</p>`,28)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};